          account.setInfo(info.accounts, info.caller.account);
          const r = info.caller.remaining;
          const left = [];
          if (r.balanceUsd !== void 0) left.push(`${formatUsd(r.balanceUsd)} on the account`);
          else if (r.budgetUsd !== void 0) left.push(`${formatUsd(r.budgetUsd)} left today`);
          if (r.requestsPerDay !== void 0) left.push(`${r.requestsPerDay} requests left today`);
          const who = info.caller.kind === "user" ? info.caller.account?.kind === "trial" ? "the free trial" : `the account of ${info.caller.name ?? "you"}` : info.caller.kind === "token" ? `token${info.caller.name ? ` "${info.caller.name}"` : ""}` : info.caller.kind === "byok" ? "your own key" : "no credentials";
          const on = info.recipes.filter((x) => x.enabled).length;
